\title{The Ternary Pythagorean Trees:\\ A Complete Classification}
\author{Aristotle}
\date{25 August 2026}

\begin{document}
\maketitle

\begin{abstract}
Let $\N = \{(m,n)\in\mathbb{Z}^2 : 1\le n<m,\ \gcd(m,n)=1,\ m+n \text{ odd}\}$ be the set of
Euclid parameters of primitive Pythagorean triples, with root $(2,1)$ corresponding to
$(3,4,5)$. We study the integer linear maps $(m,n)\mapsto(am+bn,\,cm+dn)$ that preserve $\N$,
and the triples of such maps that organise $\N$ into a rooted ternary tree. We prove: (i) a
complete, finitely checkable characterisation of the node-preserving maps, whose consequence is
the \emph{power-of-two theorem}: the determinant of any node-preserving map is nonzero and its
absolute value is a power of two, so no odd prime can divide it; (ii) a complete
classification: up to relabelling of branches there are exactly three ternary Pythagorean
trees, namely the Berggren triple (determinants $1,-1,1$), the Price triple (determinants
$2,-2,2$), and a previously overlooked \emph{mixed} triple with determinants $2,1,-2$; in
particular the conjectured Berggren/Price dichotomy is false while the accompanying bound
$|\dt|\le2$ for tree branches is true; (iii) structural corollaries valid for every such tree:
every branch strictly increases the Euclid parameter $m$, the triple $(5,12,13)$ is always a
child of $(3,4,5)$, every primitive triple is generated exactly once, the branch densities
satisfy $\sum_i 1/(a_i(a_i+b_i))=1$, and the determinant spectrum $\sum_i|\dt M_i|\in\{3,5,6\}$
separates the three trees.
\end{abstract}

\section{Introduction}

\subsection{Background}

Euclid's parametrisation sends integers $m>n\ge1$ to the Pythagorean triple
\[
  (x,y,z) = (m^2-n^2,\ 2mn,\ m^2+n^2),
\]
and it is classical that this is a bijection from
\[
  \N = \{(m,n) : 1\le n<m,\ \gcd(m,n)=1,\ m+n \text{ odd}\}
\]
onto the primitive Pythagorean triples with positive entries and even second leg. The root
$(2,1)$ corresponds to $(3,4,5)$.

It has long been known that the primitive triples can be organised into an infinite rooted
ternary tree in which every triple appears exactly once. Berggren's construction uses three
matrices of determinant $\pm1$; Price's uses three matrices of determinant $\pm2$. In Euclid
coordinates these are
\[
  A=\begin{pmatrix}2&-1\\1&0\end{pmatrix},\quad
  B=\begin{pmatrix}2&1\\1&0\end{pmatrix},\quad
  C=\begin{pmatrix}1&2\\0&1\end{pmatrix}
\]
and
\[
  P_0=\begin{pmatrix}1&1\\0&2\end{pmatrix},\quad
  P_1=\begin{pmatrix}2&0\\1&-1\end{pmatrix},\quad
  P_2=\begin{pmatrix}2&0\\1&1\end{pmatrix},
\]
acting by $(m,n)\mapsto(am+bn,\ cm+dn)$.

The classification question circulated as the conjecture: \emph{up to relabelling the only
ternary trees of integer linear maps on $\N$ with root $(2,1)$ are the Berggren triple
(determinants $\pm1$) and the Price triple (determinants $\pm2$), and no triple with
$|\dt|\ge3$ exists.}

\subsection{Results}

\begin{itemize}
  \item The determinant claim is true and can be strengthened: \emph{every} node-preserving
  integer linear map has $|\dt|$ a power of two (Theorem~\ref{thm:oddprime}). No odd prime
  divides the determinant.
  \item The classification claim is \emph{false}: there is a third tree, mixing determinant
  regimes, with branches
  \[
    F_0=\begin{pmatrix}1&3\\0&2\end{pmatrix}\ (\dt 2),\qquad A\ (\dt 1),\qquad P_1\ (\dt -2).
  \]
  \item The corrected statement is a complete classification: exactly three ternary Pythagorean
  trees exist, up to relabelling (Theorem~\ref{thm:class}); consequently every branch of every
  tree has $|\dt|\le2$ (Corollary~\ref{cor:det2}).
  \item The reason for the failure of the conjecture is that determinant is not the invariant.
  What is invariant is the $2$-adic constraint per branch, together with a \emph{density
  budget} $\sum_i 1/(a_i(a_i+b_i))=1$ per tree (Theorem~\ref{thm:density}).
\end{itemize}

\section{Definitions}

\begin{definition}[Node]
A pair $(m,n)\in\mathbb{Z}^2$ is a \emph{node} if $1\le n<m$, $\gcd(m,n)=1$ and $m+n$ is odd.
We write $\N$ for the set of nodes and call $(2,1)$ the \emph{root}.
\end{definition}

\begin{definition}[Integer map]
An \emph{integer map} is $M=(a,b;c,d)\in\mathbb{Z}^4$, acting by
$M\cdot(m,n)=(am+bn,\ cm+dn)$, with determinant $\dt M = ad-bc$. It \emph{preserves} $\N$ if
$M\cdot(m,n)\in\N$ for every $(m,n)\in\N$.
\end{definition}

\begin{definition}[Ternary Pythagorean tree]
\label{def:tree}
A triple $T=(M_0,M_1,M_2)$ of integer maps is a \emph{ternary Pythagorean tree} if
\begin{enumerate}
  \item each $M_i$ preserves $\N$;
  \item $M_i\cdot(m,n)\ne(2,1)$ for every node $(m,n)$ and every $i$;
  \item every node $\ne(2,1)$ equals $M_i\cdot(m,n)$ for some $i$ and some node $(m,n)$;
  \item if $M_i\cdot(x,y)=M_j\cdot(u,v)$ with $(x,y),(u,v)$ nodes then $i=j$, $x=u$, $y=v$.
\end{enumerate}
Conditions (2)--(4) say exactly that assigning to each non-root node its unique parent makes
$\N$ the vertex set of a rooted tree with root $(2,1)$ in which every vertex has three
labelled children.
\end{definition}

\begin{definition}[Euclid map; branch density]
For $(m,n)\in\mathbb{Z}^2$ set $\tau(m,n)=(m^2-n^2,\ 2mn,\ m^2+n^2)$. A triple $(x,y,z)$ is a
\emph{PPT} if $x^2+y^2=z^2$, $x,y>0$, $\gcd(x,y)=1$ and $y$ is even. For an integer map
$M=(a,b;c,d)$ the \emph{branch density} is $\rho(M)=1/\big(a(a+b)\big)$.
\end{definition}

\section{The obstruction and the characterisation}

\begin{lemma}[Divisor transfer]
\label{lem:bezout}
Let $M=(a,b;c,d)$, let $\gcd(m,n)=1$, and write $(X,Y)=M\cdot(m,n)$. If $g$ divides both $X$
and $Y$ then $g\mid \dt M$.
\end{lemma}

\begin{proof}
Choose $u,v$ with $um+vn=1$. Then
$(ud-vc)X + (va-ub)Y = (ad-bc)(um+vn) = \dt M$,
a $\mathbb{Z}$-linear combination of $X$ and $Y$.
\end{proof}

\begin{lemma}[Parity]
\label{lem:parity}
If $M$ preserves $\N$ then $a+c$ and $b+d$ are odd.
\end{lemma}

\begin{proof}
Apply $M$ to $(2,1)$ and $(3,2)$. Oddness of the image coordinate sums gives $2(a+c)+(b+d)$ odd
and $3(a+c)+2(b+d)$ odd; the first forces $b+d$ odd and then the second forces $a+c$ odd.
\end{proof}

\begin{lemma}[Cone conditions]
\label{lem:cone}
If $M$ preserves $\N$ then $c\ge0$, $c+d\ge0$, $(c,d)\ne(0,0)$, and the same three conditions
hold for the row $(a-c,\ b-d)$.
\end{lemma}

\begin{proof}
Preservation demands $Y=cm+dn\ge1$ and $X-Y=(a-c)m+(b-d)n\ge1$ on all nodes, so it suffices
that a linear form $\ell(m,n)=pm+qn$ which is $\ge1$ on all nodes satisfies $p\ge0$, $p+q\ge0$,
$(p,q)\ne(0,0)$. The last follows from $\ell(2,1)\ge1$. If $p\le-1$, evaluate at the node
$(m,1)$ with $m=2(|q|+2)$ even: $\ell\le -m+|q|<0$. If $p+q\le-1$, evaluate at the spine node
$(m,m-1)$ with $m=|q|+2$: $\ell=(p+q)m-q\le -m+|q|<0$.
\end{proof}

\begin{lemma}[Cone positivity]
\label{lem:conepos}
If $p\ge0$, $p+q\ge0$ and $(p,q)\ne(0,0)$ then $pm+qn\ge1$ for all integers $1\le n<m$.
\end{lemma}

\begin{proof}
If $p=0$ then $q\ge1$ and $qn\ge1$. If $p\ge1$ and $q\ge0$ then $pm+qn\ge m\ge2$. If $p\ge1$
and $q<0$ then $pm+qn>pm+qm=(p+q)m\ge0$, hence $\ge1$ by integrality.
\end{proof}

\begin{theorem}[Odd prime obstruction; power of two]
\label{thm:oddprime}
If $M$ preserves $\N$ then no odd prime divides $\dt M$. In particular $\dt M\ne0$ and
$|\dt M|$ is a power of $2$.
\end{theorem}

\begin{proof}
Suppose $p\ge3$ is prime with $p\mid\dt M$. We produce a node whose image has both coordinates
divisible by $p$, contradicting coprimality of images.

\emph{Case 1: $p\mid a$ and $p\mid c$.} Take the node $(p+1,p)$: consecutive integers are
coprime and $2p+1$ is odd. Its image $\big(a(p+1)+bp,\ c(p+1)+dp\big)$ has both entries
divisible by $p$.

\emph{Case 2: $p\nmid c$.} Choose $s$ with $cs+d\equiv0\pmod p$. Since $p$ is odd the class
$s+p\mathbb{Z}$ contains arbitrarily large even integers; pick an even $m\ge2$ with
$m\equiv s\pmod p$, so that $(m,1)$ is a node and $Y=cm+d\equiv0\pmod p$. From
$cX = c(am+b) = a(cm+d)-\dt M = aY - \dt M$ we get $p\mid cX$, hence $p\mid X$.

\emph{Case 3: $p\nmid a$.} Symmetrically choose $s$ with $as+b\equiv0\pmod p$ and an even
$m\ge2$ with $m\equiv s$; then $p\mid X$, and $aY=cX+\dt M$ gives $p\mid Y$.

The cases are exhaustive. Since $3\mid 0$, also $\dt M\ne0$; a nonzero integer with no odd
prime factor has absolute value a power of two.
\end{proof}

\begin{definition}[Admissibility]
$M=(a,b;c,d)$ is \emph{admissible} if (i) $a+c$ and $b+d$ are odd; (ii) no odd prime divides
$\dt M$; (iii) $c\ge0$, $c+d\ge0$, $(c,d)\ne(0,0)$; (iv) $a-c\ge0$, $(a-c)+(b-d)\ge0$,
$(a-c,b-d)\ne(0,0)$.
\end{definition}

\begin{theorem}[Characterisation]
\label{thm:char}
An integer map preserves $\N$ if and only if it is admissible.
\end{theorem}

\begin{proof}
Necessity is Lemmas~\ref{lem:parity}, \ref{lem:cone} and Theorem~\ref{thm:oddprime}. For
sufficiency let $M$ be admissible, $(m,n)$ a node, $(X,Y)=M\cdot(m,n)$. First,
$X+Y=(a+c)m+(b+d)n$ is odd, since $a+c,b+d$ are odd and $m+n$ is odd. Second,
Lemma~\ref{lem:conepos} applied to $(c,d)$ gives $Y\ge1$ and applied to $(a-c,b-d)$ gives
$X-Y\ge1$, so $1\le Y<X$. Third, if a prime $q$ divides $\gcd(X,Y)$ then $q\mid \dt M$ by
Lemma~\ref{lem:bezout}; $q=2$ contradicts $X+Y$ odd and $q$ odd contradicts (ii). Hence
$(X,Y)\in\N$.
\end{proof}

Theorem~\ref{thm:char} is effective: admissibility involves linear inequalities, two parities
and the factorisation of one integer, so the node-preserving maps in any box
$|a|,|b|,|c|,|d|\le R$ can be enumerated exactly.

\section{Rigidity: what every tree must do}

Throughout, $M$ is node-preserving and $T=(M_0,M_1,M_2)$ is a ternary Pythagorean tree.

\begin{lemma}[Positivity of the top row]
\label{lem:apos}
$a\ge1$ and $a+b\ge1$.
\end{lemma}

\begin{proof}
Since $c\ge0$ and $a\ge c$ we get $a\ge0$; if $a=0$ then $c=0$ and $\dt M=0$, contradicting
Theorem~\ref{thm:oddprime}. Adding the cone inequalities gives
$a+b = \big[(a-c)+(b-d)\big]+(c+d)\ge0$. Suppose $a+b=0$, i.e. $b=-a$. If $c+d\ge1$, evaluate
at the spine nodes $(m,m-1)$: the first image coordinate is $am+b(m-1)=a$, constant, while the
second is $(c+d)m-c\to\infty$, contradicting $Y<X$. Hence $c+d=0$ and
$\dt M=ad-bc=ad+ac=a(c+d)=0$, again a contradiction.
\end{proof}

\begin{lemma}[Root minimality]
\label{lem:rootmin}
For every node $(m,n)$ we have $(M\cdot(m,n))_1 \ge 2a+b$, with equality at the root.
\end{lemma}

\begin{proof}
If $b\ge0$ then $am+bn\ge2a+b$ since $m\ge2$, $n\ge1$. If $b<0$ then $n\le m-1$ gives
$bn\ge b(m-1)$, so $am+bn\ge(a+b)m-b\ge2(a+b)-b=2a+b$ using $a+b\ge1$ and $m\ge2$.
\end{proof}

\begin{lemma}[No identity branch]
\label{lem:noid}
If $M$ preserves $\N$ with $a=1$, $b=0$, then $c=0$ and $d=1$, so $M$ is the identity.
Consequently no branch of a tree has top row $(1,0)$, since the identity fixes the root and
violates axiom (2) of Definition~\ref{def:tree}.
\end{lemma}

\begin{proof}
$0\le c\le a=1$ and parity of $a+c$ force $c=0$. Then $c+d\ge0$ and $(c,d)\ne(0,0)$ give
$d\ge1$; parity of $b+d$ makes $\dt M=d$ odd, and $|\dt M|$ is a power of two, so $d=1$.
\end{proof}

\begin{theorem}[Growth]
\label{thm:growth}
Every branch of a ternary Pythagorean tree strictly increases the first Euclid parameter:
$(M_i\cdot(m,n))_1>m$ for every node $(m,n)$.
\end{theorem}

\begin{proof}
Write $X=am+bn$. If $b\ge1$ then $X\ge m+1>m$. If $b=0$ then $a\ge2$ by Lemma~\ref{lem:noid},
so $X=am\ge2m>m$. If $b<0$ then $X\ge(a+b)m-b\ge m-b>m$, using $a+b\ge1$ and $n\le m-1$.
\end{proof}

\begin{theorem}[Forced root child]
\label{thm:rootchild}
In every ternary Pythagorean tree there is exactly one index $i$ with $M_i\cdot(2,1)=(3,2)$.
\end{theorem}

\begin{proof}
$(3,2)$ is a non-root node, so it has a parent $(x,y)$ via some branch $i$; by
Theorem~\ref{thm:growth}, $x<3$, and $(2,1)$ is the only node with $m<3$. Uniqueness of $i$ is
axiom (4).
\end{proof}

\begin{theorem}[Generation]
\label{thm:gen}
In every ternary Pythagorean tree, every node is obtained from $(2,1)$ by a finite word in the
three branches.
\end{theorem}

\begin{proof}
Strong induction on $m$. If $(m,n)=(2,1)$ we are done; otherwise axiom (3) gives a parent
$(x,y)$ with $x<m$ by Theorem~\ref{thm:growth}, and the induction terminates since $m\ge2$ on
$\N$.
\end{proof}

\section{Three trees}

\begin{theorem}[Berggren]
\label{thm:berg}
The triple $\{A,B,C\}$ with $A\cdot(m,n)=(2m-n,\,m)$, $B\cdot(m,n)=(2m+n,\,m)$,
$C\cdot(m,n)=(m+2n,\,n)$, of determinants $1,-1,1$, is a ternary Pythagorean tree.
\end{theorem}

\begin{proof}[Proof sketch: descent by ratio]
For a non-root node $(m,n)$ compare $m$ with $2n$ and $3n$. If $m<2n$ the parent is
$(n,\,2n-m)$ via $A$. If $m=2n$ then coprimality forces $n=1$ and $(m,n)$ is the root. If
$2n<m<3n$ the parent is $(n,\,m-2n)$ via $B$. If $m=3n$ then $n=1$, $m=3$, and $m+n$ is even --
impossible. If $m>3n$ the parent is $(m-2n,\,n)$ via $C$. Each proposed parent is a node: the
inequalities are immediate, coprimality follows because the inverse substitution is unimodular,
and parity is preserved. The images are the disjoint regions $m<2n$, $2n<m<3n$, $3n<m$, giving
uniqueness of the branch and non-attainment of the root; injectivity within a branch follows
from $\dt\ne0$.
\end{proof}

\begin{theorem}[Price]
\label{thm:price}
The triple $\{P_0,P_1,P_2\}$ with $P_0\cdot(m,n)=(m+n,\,2n)$, $P_1\cdot(m,n)=(2m,\,m-n)$,
$P_2\cdot(m,n)=(2m,\,m+n)$, of determinants $2,-2,2$, is a ternary Pythagorean tree.
\end{theorem}

\begin{proof}[Proof sketch: descent by parity and halving]
If $n=2k$ is even then $\gcd(m,k)=1$ and the parent is $(m-k,\,k)$ via $P_0$. If $n$ is odd
then $m=2j$ is even with $\gcd(j,n)=1$; for $n<j$ the parent is $(j,\,j-n)$ via $P_1$; for
$n=j$ we get $m=2n$, hence the root; for $n>j$ the parent is $(j,\,n-j)$ via $P_2$. The images
are the disjoint regions ``$n$ even'', ``$m$ even and $2n<m$'', ``$m$ even and $m<2n$''.
\end{proof}

\begin{theorem}[The mixed tree]
\label{thm:mixed}
The triple $\{F_0,A,P_1\}$ with $F_0\cdot(m,n)=(m+3n,\,2n)$, $A\cdot(m,n)=(2m-n,\,m)$,
$P_1\cdot(m,n)=(2m,\,m-n)$, of determinants $2,1,-2$, is a ternary Pythagorean tree.
\end{theorem}

\begin{proof}[Proof sketch: hybrid descent]
If $m<2n$ the \emph{ratio} rule applies: parent $(n,\,2n-m)$ via $A$. If $m=2n$ we are at the
root. If $m>2n$ the \emph{parity} rule applies: for $n=2k$ even the parent is $(m-3k,\,k)$ via
$F_0$, where $m-3k>k$ precisely because $m>2n=4k$; for $n$ odd, $m=2j$ is even and the parent
is $(j,\,j-n)$ via $P_1$, with $j>n$ because $m>2n$. The three image regions -- $\{m<2n\}$ for
$A$, $\{n$ even, $2n<m\}$ for $F_0$, and $\{m$ even, $n$ odd, $2n<m\}$ for $P_1$ -- are
pairwise disjoint: the first is separated by the ratio, and the last two by the parity of the
second coordinate ($F_0$ outputs $2n$, while the second coordinate $m-n$ of a $P_1$-image is
odd because $m+n$ is odd).
\end{proof}

\begin{theorem}[Refutation of the dichotomy]
There is a ternary Pythagorean tree whose determinants are neither all $\pm1$ nor all $\pm2$;
hence the conjecture that every such tree is a relabelling of Berggren's or Price's is false.
\end{theorem}

\begin{proof}
The mixed tree has determinant multiset $\{2,1,-2\}$, which is invariant under relabelling and
equals neither $\{\pm1,\pm1,\pm1\}$ nor $\{\pm2,\pm2,\pm2\}$.
\end{proof}

\section{The classification}

\begin{lemma}[Small nodes]
\label{lem:small}
The nodes with $m\le5$ are exactly $(2,1),(3,2),(4,1),(4,3),(5,2),(5,4)$. Moreover $(2,1)$ is
the only node with $m\le2$ and $(3,2)$ the only one with $m=3$.
\end{lemma}

The images of the seven relevant matrices are exactly the following regions of $\N$:

\begin{center}
\begin{tabular}{ll}
\toprule
matrix & image of $\N$\\
\midrule
$A=(2,-1;1,0)$ & $\{m<2n\}$\\
$B=(2,1;1,0)$ & $\{2n<m<3n\}$\\
$C=(1,2;0,1)$ & $\{3n<m\}$\\
$P_0=(1,1;0,2)$ & $\{n \text{ even}\}$\\
$P_1=(2,0;1,-1)$ & $\{m \text{ even},\ 2n<m\}$\\
$P_2=(2,0;1,1)$ & $\{m \text{ even},\ m<2n\}$\\
$F_0=(1,3;0,2)$ & $\{n \text{ even},\ 2n<m\}$\\
\bottomrule
\end{tabular}
\end{center}

\paragraph{Root-child rigidity.} For node-preserving $M$, the value $M\cdot(2,1)=(2a+b,\,2c+d)$
pins $M$ to a short list: the two linear equations, the cone bounds on $c$, the parity tie
between $a$ and $c$, and the determinant conditions (nonzero, not divisible by $3$) leave
\begin{align*}
  M\cdot(2,1)=(3,2) &\implies M\in\{A,\ P_0\},\\
  M\cdot(2,1)=(4,1) &\implies M\in\{C,\ P_1\},\\
  M\cdot(2,1)=(4,3) &\implies M\in\{P_2,\ E_{43}\},\quad E_{43}=(3,-2;2,-1),\ \dt=1,\\
  M\cdot(2,1)=(5,2) &\implies M\in\{F_0,\ B,\ E_{52}\},\quad E_{52}=(3,-1;2,-2),\ \dt=-4.
\end{align*}
The \emph{exotic} maps $E_{43}$, $E_{52}$ do preserve $\N$; they are eliminated by the covering
axiom rather than by admissibility. Note $|\dt E_{52}|=4$: individual node-preserving maps may
exceed determinant $2$, even though tree branches never do.

\begin{theorem}[Classification]
\label{thm:class}
Let $T=(M_0,M_1,M_2)$ be a ternary Pythagorean tree. Then as a set
\[
  \{M_0,M_1,M_2\} = \{A,B,C\}\quad\text{or}\quad\{P_0,P_1,P_2\}\quad\text{or}\quad
  \{F_0,A,P_1\},
\]
and conversely each of these three sets is a ternary Pythagorean tree. Hence, up to relabelling
of branches, there are exactly three ternary Pythagorean trees.
\end{theorem}

\begin{proof}
By Theorem~\ref{thm:rootchild} exactly one branch $M_{i_0}$ satisfies $M_{i_0}\cdot(2,1)=(3,2)$,
and root-child rigidity gives $M_{i_0}\in\{A,P_0\}$.

\emph{Case I: $M_{i_0}=A$.} The image of $A$ is $\{m<2n\}$, so by axiom (4) the other two
branches map into $\{2n<m\}$ (the ray $m=2n$ meets $\N$ only at the root). The node $(4,1)$ is
covered by some branch $j\ne i_0$. Root minimality (Lemma~\ref{lem:rootmin}) gives
$(M_j\cdot(2,1))_1\le4$, axiom (2) with Lemma~\ref{lem:small} gives $(M_j\cdot(2,1))_1\ge3$, and
the region constraint plus the list of small nodes force $M_j\cdot(2,1)=(4,1)$; hence
$M_j\in\{C,P_1\}$.

\emph{Subcase I.a: $M_j=C$.} Since the image of $C$ is $\{3n<m\}$, the third branch $M_k$ maps
into $\{2n<m<3n\}$. The node $(5,2)$ lies there and must be covered by $k$; root minimality and
Lemma~\ref{lem:small} force $M_k\cdot(2,1)=(5,2)$, so $M_k\in\{F_0,B,E_{52}\}$. The node
$(8,3)$ also lies in $\{2n<m<3n\}$ and must be covered by $k$, but $F_0$ and $E_{52}$ always
output an even second coordinate. Hence $M_k=B$ and $T$ is Berggren's tree.

\emph{Subcase I.b: $M_j=P_1$.} The image of $P_1$ is $\{m$ even, $2n<m\}$, so $M_k$ always
produces odd first coordinates. The node $(5,2)$ must be covered by $k$, and as before
$M_k\cdot(2,1)=(5,2)$, so $M_k\in\{F_0,B,E_{52}\}$. Now $B\cdot(3,2)=(8,3)$ has even first
coordinate, excluded; and $E_{52}$ cannot produce $(9,4)$, which $k$ must cover. Hence
$M_k=F_0$ and $T$ is the mixed tree.

\emph{Case II: $M_{i_0}=P_0$.} The image of $P_0$ is $\{n$ even$\}$, so the other branches
always produce odd second coordinates. The node $(4,1)$ is covered by some $j\ne i_0$, and the
root-minimality argument (using oddness of $(M_j\cdot(2,1))_2$) forces $M_j\cdot(2,1)=(4,1)$,
so $M_j\in\{C,P_1\}$; but $C\cdot(3,2)=(7,2)$ has even second coordinate, so $M_j=P_1$. The
third branch then produces nodes with odd $n$ and (by parity) even $m$, and with $m<2n$. The
node $(4,3)$ must be covered by $k$, and root minimality forces $M_k\cdot(2,1)=(4,3)$, so
$M_k\in\{P_2,E_{43}\}$; but $E_{43}\cdot(3,2)=(5,4)$ has even second coordinate. Hence
$M_k=P_2$ and $T$ is Price's tree.

The converse is Theorems~\ref{thm:berg}, \ref{thm:price}, \ref{thm:mixed}. Finally the three
branches of any tree are pairwise distinct (if $M_i=M_j$ then $M_i\cdot(2,1)=M_j\cdot(2,1)$ and
axiom (4) gives $i=j$), so the set determines the triple up to relabelling.
\end{proof}

\begin{corollary}[The corrected quantitative claim]
\label{cor:det2}
Every branch of every ternary Pythagorean tree has $|\dt|\le2$. In particular no such tree has
a branch of determinant of absolute value $\ge3$.
\end{corollary}

\section{The dictionary with primitive Pythagorean triples}

\begin{theorem}[Euclid correspondence]
\label{thm:euclid}
The map $\tau(m,n)=(m^2-n^2,\ 2mn,\ m^2+n^2)$ is a bijection from $\N$ onto the primitive
Pythagorean triples with positive entries and even second leg, with $\tau(2,1)=(3,4,5)$.
\end{theorem}

\begin{proof}[Proof sketch]
Well-definedness: the Pythagorean identity is formal, positivity follows from $m>n\ge1$, and
primitivity and leg parity follow from $\gcd(m,n)=1$ with $m+n$ odd via the coprime
classification of Pythagorean triples. Injectivity: adding and subtracting the first and third
coordinates gives $m^2=m'^2$ and $n^2=n'^2$, and positivity concludes. Surjectivity: the
coprime classification produces $m,n$ with $x=\pm(m^2-n^2)$, $y=2mn$, $z=\pm(m^2+n^2)$; the
hypothesis that the second leg is even selects the branch $x=m^2-n^2$ (since $m^2-n^2$ is odd
when $m+n$ is odd); replacing $(m,n)$ by $(-m,-n)$ if needed makes both positive, and $x>0$
gives $n<m$.
\end{proof}

\begin{theorem}[Generation of all triples]
Let $T$ be any ternary Pythagorean tree. Every primitive Pythagorean triple with even second
leg is $\tau$ of a node reachable from $(2,1)$ by a finite word in the three branches, and it
occurs for exactly one node.
\end{theorem}

\begin{proof}
Combine Theorem~\ref{thm:euclid} with Theorem~\ref{thm:gen}; uniqueness is injectivity of
$\tau$.
\end{proof}

The first generation from $(3,4,5)$ is:

\begin{center}
\begin{tabular}{ll}
\toprule
tree & children of $(3,4,5)$\\
\midrule
Berggren & $(5,12,13)$, $(21,20,29)$, $(15,8,17)$\\
Price & $(5,12,13)$, $(15,8,17)$, $(7,24,25)$\\
Mixed & $(21,20,29)$, $(5,12,13)$, $(15,8,17)$\\
\bottomrule
\end{tabular}
\end{center}

By Theorem~\ref{thm:rootchild}, $(5,12,13)$ is a child of $(3,4,5)$ in \emph{every} ternary
Pythagorean tree.

\section{Conservation of branch density and the determinant spectrum}

Fix a node-preserving $M$ with top row $(a,b)$, so $a\ge1$ and $a+b\ge1$. The nodes whose
$M$-image has first coordinate at most $B$ are the lattice points of the triangle
$\{(x,y): 0<y<x,\ ax+by\le B\}$ with vertices $(0,0)$, $(B/a,0)$, $(B/(a+b),B/(a+b))$, of area
$B^2/\big(2a(a+b)\big)$, while the full cone slice $\{0<y<x\le B\}$ has area $B^2/2$. Hence the
proportion of nodes produced by $M$ is $\rho(M)=1/\big(a(a+b)\big)$. Explicitly
\[
  \rho(A)=\tfrac12,\quad \rho(B)=\tfrac16,\quad \rho(C)=\tfrac13,\quad
  \rho(P_0)=\tfrac12,\quad \rho(P_1)=\rho(P_2)=\tfrac14,\quad \rho(F_0)=\tfrac14.
\]

\begin{theorem}[Branch-density conservation]
\label{thm:density}
For every ternary Pythagorean tree, $\rho(M_0)+\rho(M_1)+\rho(M_2)=1$.
\end{theorem}

\begin{proof}
By Theorem~\ref{thm:class} there are three cases, and
$\tfrac12+\tfrac16+\tfrac13=\tfrac12+\tfrac14+\tfrac14=\tfrac14+\tfrac12+\tfrac14=1$.
\end{proof}

Read as a constraint, the identity is the \emph{budget equation}
\[
  \frac{1}{a_0(a_0+b_0)}+\frac{1}{a_1(a_1+b_1)}+\frac{1}{a_2(a_2+b_2)} = 1,
\]
whose realisable solutions have denominator multisets $\{2,6,3\}$ and $\{2,4,4\}$ -- and the
second is realised by \emph{two} distinct matrix triples, Price's and the hybrid. That is why
there are three trees and not two.

\begin{theorem}[Determinant spectrum]
For every ternary Pythagorean tree,
$|\dt M_0|+|\dt M_1|+|\dt M_2|\in\{3,5,6\}$, with value $3$ for Berggren, $6$ for Price and $5$
for the mixed tree; in particular the sum never exceeds $6$.
\end{theorem}

\section{Computational evidence}

Theorem~\ref{thm:char} turns node preservation into a finite test.

\paragraph{Admissible maps in a box.} Enumerating all $(a,b,c,d)$ with entries bounded by $R$ in
absolute value and applying the characterisation gives

\begin{center}
\begin{tabular}{lrrrrrrrr}
\toprule
$R$ & 1 & 2 & 3 & 4 & 5 & 6 & 7 & 8\\
\midrule
\# node-preserving maps & 1 & 8 & 18 & 39 & 67 & 93 & 138 & 197\\
largest $|\dt|$ observed & 1 & 4 & 8 & 16 & 32 & 32 & 32 & 64\\
\bottomrule
\end{tabular}
\end{center}

and in every box the set of determinant magnitudes consists precisely of the powers of two up
to the maximum shown, in agreement with Theorem~\ref{thm:oddprime}.

\paragraph{Validation.} Comparing the criterion of Theorem~\ref{thm:char} with direct
verification of node preservation on all nodes with $m\le200$, over all $13^4=28561$ matrices
with entries in $[-6,6]$, produced no disagreements.

\paragraph{Exhaustive tree search.} Among the $197$ node-preserving maps with entries bounded by
$8$, the triples whose images partition $\{(m,n)\in\N : m\le200\}\setminus\{(2,1)\}$ are exactly
three: Price's, Berggren's and the mixed triple, matching Theorem~\ref{thm:class}.

\section{Discussion}

The two classical trees implement two different splitting principles on the cone $0<n<m$:
Berggren splits by \emph{ratio} ($m/n\in(1,2),(2,3),(3,\infty)$), Price by \emph{parity and
halving}. The mixed tree shows the principles compose: use the ratio rule on $m<2n$ and the
parity rule on $m>2n$. That the composition closes into a tree is dictated by the density
budget: the ratio rule on $m<2n$ costs exactly $\tfrac12$, the same as $P_0$, and the remaining
$\tfrac12$ can be paid by $\{P_1,F_0\}$ as well as by $\{P_1,P_2\}$.

Each tree yields an enumeration of all primitive Pythagorean triples exactly once, with $O(1)$
arithmetic per triple and no duplication or gcd tests; the density values $\tfrac12,\tfrac16,
\tfrac13$ versus $\tfrac12,\tfrac14,\tfrac14$ versus $\tfrac14,\tfrac12,\tfrac14$ predict the
shape of the truncated trees and hence the best traversal for a bounded-hypotenuse search. The
power-of-two theorem also gives a fast rejection test: an integer matrix whose determinant has
an odd prime factor cannot occur in such a scheme.

The conjecture failed because determinant looked like the invariant: both classical trees have
uniform determinant. Determinant is not preserved by the operations that build trees
(region-splitting and re-pairing of branches). The genuine invariants are the $2$-adic
constraint per branch and the density budget per tree; organised around the budget equation,
the third solution appears immediately.

\section{Future directions}

\begin{itemize}
  \item \textbf{Arity $k$.} The budget becomes $\sum_{i<k}1/\big(a_i(a_i+b_i)\big)=1$. The
  number $t(k)$ of $k$-ary trees on $\N$ with root $(2,1)$ should be finite for all $k$, with
  $t(2)=0$, $t(3)=3$ and $t(k)\ge3$ for $k\ge3$; and the bound $|\dt|\le2$ per branch should be
  arity-independent.
  \item \textbf{Other parameter sets.} Replacing $\N$ by the Euclid parameters of triples in an
  imaginary quadratic order, or of almost-primitive triples, changes the parity condition and
  hence the obstruction. Which prime obstructions survive?
  \item \textbf{Affine child rules.} Allowing $(m,n)\mapsto(am+bn+e,\ cm+dn+f)$ breaks the
  Bézout identity of Lemma~\ref{lem:bezout}; do new trees appear?
  \item \textbf{Metric comparison.} The three trees induce three tree metrics on the primitive
  triples; the depth of a triple of hypotenuse $z$ differs across them because the growth rate
  of $m$ per step is exactly $2$ for $P_1,P_2$ but varies between $1$ and $3$ for Berggren's.
  \item \textbf{Budget-only proofs.} Can Corollary~\ref{cor:det2} be derived directly from the
  budget equation plus the power-of-two theorem, without the full classification? Such an
  argument would generalise to all arities at once.
\end{itemize}

\section{Conclusion}

Any integer linear rule acting on Euclid parameters has determinant a power of two -- an
obstruction traceable to a single Bézout identity -- and any complete ternary child rule is one
of exactly three: Berggren's ratio tree, Price's halving tree, and a hybrid that had been
overlooked. The classical dichotomy is false; the classical determinant ceiling is true and is
a shadow of a $2$-adic phenomenon. Behind both stands an accounting identity: the three
branches occupy densities summing to exactly one, and the trees are precisely the ways of
paying that bill.

\end{document}

