"""
Algorithm 2 — Exact-cover search for ternary Pythagorean trees.

Enumerates every triple of node-preserving integer maps whose images partition the
non-root nodes inside a finite window.  Instead of testing all C(K, 3) triples of
the K admissible maps, the search uses the exact-cover principle: the smallest
uncovered node must be covered by *some* chosen branch, which prunes the tree of
possibilities to a handful of nodes.
"""

from __future__ import annotations

from itertools import product
from math import gcd
from typing import Dict, List, Set, Tuple

Node = Tuple[int, int]
IntMap = Tuple[int, int, int, int]


def is_node(m: int, n: int) -> bool:
    return 1 <= n < m and gcd(m, n) == 1 and (m + n) % 2 == 1


def nodes_up_to(bound: int) -> List[Node]:
    return [(m, n) for m in range(2, bound + 1) for n in range(1, m) if is_node(m, n)]


def det(M: IntMap) -> int:
    a, b, c, d = M
    return a * d - b * c


def has_odd_prime_factor(k: int) -> bool:
    if k == 0:
        return True
    k = abs(k)
    while k % 2 == 0:
        k //= 2
    return k > 1


def preserves(M: IntMap) -> bool:
    a, b, c, d = M
    def cone(p: int, q: int) -> bool:
        return p >= 0 and p + q >= 0 and not (p == 0 and q == 0)
    return ((a + c) % 2 != 0 and (b + d) % 2 != 0
            and not has_odd_prime_factor(det(M))
            and cone(c, d) and cone(a - c, b - d))


def admissible_maps(radius: int) -> List[IntMap]:
    rng = range(-radius, radius + 1)
    return [M for M in product(rng, rng, rng, rng) if preserves(M)]


def apply_map(M: IntMap, node: Node) -> Node:
    a, b, c, d = M
    m, n = node
    return (a * m + b * n, c * m + d * n)


def search_trees(radius: int, bound: int) -> List[Tuple[IntMap, ...]]:
    """
    All triples of node-preserving maps with |entries| <= radius whose images
    partition {(m,n) node : m <= bound} \\ {(2,1)}.
    """
    window = nodes_up_to(bound)
    targets: Set[Node] = set(window) - {(2, 1)}

    candidates: List[Tuple[IntMap, Set[Node]]] = []
    for M in admissible_maps(radius):
        images = {apply_map(M, nd) for nd in window}
        if (2, 1) in images:                       # the root would acquire a parent
            continue
        inside = {img for img in images if img[0] <= bound}
        if inside and inside <= targets:
            candidates.append((M, inside))

    found: List[Tuple[IntMap, ...]] = []

    def extend(chosen: List[IntMap], covered: Set[Node]) -> None:
        if len(chosen) == 3:
            if covered == targets:
                found.append(tuple(chosen))
            return
        remaining = targets - covered
        if not remaining:
            return
        goal = min(remaining)                      # forced: this node needs a parent
        for M, img in candidates:
            if goal in img and not (img & covered):
                extend(chosen + [M], covered | img)

    extend([], set())
    return found


if __name__ == "__main__":
    LABELS: Dict[frozenset, str] = {
        frozenset({(2, -1, 1, 0), (2, 1, 1, 0), (1, 2, 0, 1)}): "Berggren",
        frozenset({(1, 1, 0, 2), (2, 0, 1, -1), (2, 0, 1, 1)}): "Price",
        frozenset({(1, 3, 0, 2), (2, -1, 1, 0), (2, 0, 1, -1)}): "Mixed",
    }
    for radius, bound in ((8, 40), (8, 60), (8, 90)):
        trees = search_trees(radius, bound)
        print(f"radius {radius}, window m <= {bound}:  {len(trees)} trees")
        for T in trees:
            name = LABELS.get(frozenset(T), "UNKNOWN")
            print(f"    {T}   dets {[det(M) for M in T]}   [{name}]")

"""
Algorithm 3 — Root descent: the ancestry of a primitive Pythagorean triple.

Given a primitive Pythagorean triple with even second leg, recover its Euclid
parameters and walk them back to the root (2, 1) = (3, 4, 5) inside any of the
three ternary Pythagorean trees, producing the unique word in the branch labels
that generates the triple from the root.

Each tree supplies a total parent function on the non-root nodes:

  Berggren (ratio rule)
      m < 2n            -> (n, 2n - m)        branch A
      2n < m < 3n       -> (n, m - 2n)        branch B
      3n < m            -> (m - 2n, n)        branch C
  Price (parity rule)
      n even            -> (m - n/2, n/2)     branch P0
      n odd, m/2 > n    -> (m/2, m/2 - n)     branch P1
      n odd, m/2 < n    -> (m/2, n - m/2)     branch P2
  Mixed (hybrid rule)
      m < 2n            -> (n, 2n - m)        branch A
      m > 2n, n even    -> (m - 3n/2, n/2)    branch F0
      m > 2n, n odd     -> (m/2, m/2 - n)     branch P1

Termination is guaranteed because every branch strictly increases the first Euclid
parameter, so every parent step strictly decreases it.
"""

from __future__ import annotations

from math import gcd, isqrt
from typing import Callable, Dict, List, Optional, Tuple

Node = Tuple[int, int]
Step = Tuple[str, Node]


def is_node(m: int, n: int) -> bool:
    return 1 <= n < m and gcd(m, n) == 1 and (m + n) % 2 == 1


def to_triple(m: int, n: int) -> Tuple[int, int, int]:
    return (m * m - n * n, 2 * m * n, m * m + n * n)


def euclid_parameters(x: int, y: int, z: int) -> Node:
    """Invert Euclid's map on a primitive triple with even second leg."""
    m, n = isqrt((z + x) // 2), isqrt((z - x) // 2)
    if to_triple(m, n) != (x, y, z) or not is_node(m, n):
        raise ValueError(f"({x}, {y}, {z}) is not a primitive triple with even second leg")
    return (m, n)


def parent_berggren(node: Node) -> Optional[Step]:
    m, n = node
    if (m, n) == (2, 1):
        return None
    if m < 2 * n:
        return ("A", (n, 2 * n - m))
    if m < 3 * n:
        return ("B", (n, m - 2 * n))
    return ("C", (m - 2 * n, n))


def parent_price(node: Node) -> Optional[Step]:
    m, n = node
    if (m, n) == (2, 1):
        return None
    if n % 2 == 0:
        return ("P0", (m - n // 2, n // 2))
    return ("P1", (m // 2, m // 2 - n)) if m // 2 > n else ("P2", (m // 2, n - m // 2))


def parent_mixed(node: Node) -> Optional[Step]:
    m, n = node
    if (m, n) == (2, 1):
        return None
    if m < 2 * n:
        return ("A", (n, 2 * n - m))
    if n % 2 == 0:
        return ("F0", (m - 3 * (n // 2), n // 2))
    return ("P1", (m // 2, m // 2 - n))


PARENTS: Dict[str, Callable[[Node], Optional[Step]]] = {
    "Berggren": parent_berggren,
    "Price": parent_price,
    "Mixed": parent_mixed,
}


def ancestry(node: Node, tree: str) -> List[str]:
    """The branch word taking the root (2,1) to `node`, read left to right."""
    parent = PARENTS[tree]
    word: List[str] = []
    current = node
    while True:
        step = parent(current)
        if step is None:
            return list(reversed(word))
        label, up = step
        assert is_node(*up) and up[0] < current[0], "descent must decrease m"
        word.append(label)
        current = up


if __name__ == "__main__":
    samples = [(3, 4, 5), (5, 12, 13), (7, 24, 25), (21, 20, 29),
               (63, 16, 65), (4485, 5852, 7373)]
    for triple in samples:
        m, n = euclid_parameters(*triple)
        words = {t: "·".join(ancestry((m, n), t)) or "(root)" for t in PARENTS}
        print(f"{str(triple):>22}  (m,n) = ({m},{n})")
        for tree, word in words.items():
            print(f"       {tree:9s} {word}")
